-- Declares the sfx-api frontdoor SEJ (frontdoor.sej.v1.json) and the two capabilities that run it on the kernel's
-- transformation port: resolve-api-request (entry resolve-request) and compose-api-response (entry compose-response).
-- One transaction; nothing commits unless every declaration succeeds.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lk int;
EXEC @lk = sys.sp_getapplock @Resource = N'sidefx:model-write', @LockMode = N'Update', @LockOwner = N'Transaction', @LockTimeout = 30000;
IF @lk < 0 THROW 51000, N'MODEL_WRITE_LOCK_UNAVAILABLE', 1;

