EXEC model.declare_transformation @namespace = N'sidefx:capability:resolve-api-request', @declared_id = N'match-operation',
  @semantics_json = N'{"id":"match-operation","expression":{"op":"find","from":{"op":"path","path":"interface.operations"},"as":"operation","where":{"op":"if","when":{"op":"equals","left":{"op":"path","from":"operation","path":"method"},"right":{"op":"path","path":"request.method"}},"then":{"op":"if","when":{"op":"equals","left":{"op":"length","value":{"op":"object-entries","value":{"op":"path","from":"operation","path":"segments"}}},"right":{"op":"length","value":{"op":"path","path":"request.segments"}}},"then":{"op":"every","from":{"op":"object-entries","value":{"op":"path","from":"operation","path":"segments"}},"as":"segment","where":{"op":"if","when":{"op":"equals","left":{"op":"type","value":{"op":"path","from":"segment","path":"value"}},"right":{"op":"literal","value":"object"}},"then":{"op":"literal","value":true},"else":{"op":"equals","left":{"op":"path","from":"segment","path":"value"},"right":{"op":"lookup","value":{"op":"path","path":"request.segments"},"path":{"op":"path","from":"segment","path":"key"}}}}},"else":{"op":"literal","value":false}},"else":{"op":"literal","value":false}}}}';
EXEC model.declare_transformation @namespace = N'sidefx:capability:resolve-api-request', @declared_id = N'admit-caller',
  @semantics_json = N'{"id":"admit-caller","expression":{"op":"if","when":{"op":"equals","left":{"op":"type","value":{"op":"path","path":"caller"}},"right":{"op":"literal","value":"null"}},"then":{"op":"literal","value":false},"else":{"op":"includes","in":{"op":"path","path":"operation.callers"},"value":{"op":"path","path":"caller.kind"}}}}';
EXEC model.declare_transformation @namespace = N'sidefx:capability:resolve-api-request', @declared_id = N'resolve-operation',
  @semantics_json = N'{"id":"resolve-operation","expression":{"op":"let","bindings":{"parsed":{"op":"try-parse-json","value":{"op":"path","path":"request.body"},"stripBom":true}},"value":{"op":"let","bindings":{"context":{"op":"object","fields":{"$path":{"op":"call","target":"bind-parameters","value":{"op":"object","fields":{"operation":{"op":"path","path":"operation"},"request":{"op":"path","path":"request"}}}},"$query":{"op":"path","path":"request.query"},"$caller":{"op":"path","path":"caller"},"$body":{"op":"path","from":"parsed","path":"value"}}}},"value":{"op":"object","fields":{"contractId":{"op":"literal","value":"api-resolution.v1"},"disposition":{"op":"literal","value":"RESOLVED"},"operationId":{"op":"path","path":"operation.operationId"},"kind":{"op":"path","path":"operation.resolves.kind"},"executionTarget":{"op":"path","path":"operation.resolves.capabilityId"},"executionNamespace":{"op":"literal","value":"sidefx:capabilities"},"executionScenario":{"op":"path","path":"operation.resolves.capabilityId"},"inputType":{"op":"literal","value":"json"},"dispatchRequest":{"op":"call","target":"bind-input","value":{"op":"object","fields":{"template":{"op":"path","path":"operation.input"},"context":{"op":"path","from":"context","path":""}}}}}}}}}';
