  @semantics_json = N'{"id":"bind-parameters","expression":{"op":"object-from-entries","value":{"op":"map","from":{"op":"filter","from":{"op":"object-entries","value":{"op":"path","path":"operation.segments"}},"as":"segment","where":{"op":"equals","left":{"op":"type","value":{"op":"path","from":"segment","path":"value"}},"right":{"op":"literal","value":"object"}}},"as":"segment","value":{"op":"object","fields":{"key":{"op":"path","from":"segment","path":"value.param"},"value":{"op":"lookup","value":{"op":"path","path":"request.segments"},"path":{"op":"path","from":"segment","path":"key"}}}}}}}';
