  @semantics_json = N'{"id":"bind-input","expression":{"op":"let","bindings":{"kind":{"op":"type","value":{"op":"path","path":"template"}}},"value":{"op":"if","when":{"op":"equals","left":{"op":"path","from":"kind","path":""},"right":{"op":"literal","value":"object"}},"then":{"op":"object-from-entries","value":{"op":"filter","from":{"op":"map","from":{"op":"object-entries","value":{"op":"path","path":"template"}},"as":"member","value":{"op":"object","fields":{"key":{"op":"path","from":"member","path":"key"},"value":{"op":"call","target":"bind-input","value":{"op":"object","fields":{"template":{"op":"path","from":"member","path":"value"},"context":{"op":"path","path":"context"}}}}}}},"as":"member","where":{"op":"if","when":{"op":"equals","left":{"op":"type","value":{"op":"path","from":"member","path":"value"}},"right":{"op":"literal","value":"null"}},"then":{"op":"literal","value":false},"else":{"op":"literal","value":true}}}},"else":{"op":"if","when":{"op":"equals","left":{"op":"path","from":"kind","path":""},"right":{"op":"literal","value":"array"}},"then":{"op":"map","from":{"op":"path","path":"template"},"as":"item","value":{"op":"call","target":"bind-input","value":{"op":"object","fields":{"template":{"op":"path","from":"item","path":""},"context":{"op":"path","path":"context"}}}}},"else":{"op":"if","when":{"op":"if","when":{"op":"equals","left":{"op":"path","from":"kind","path":""},"right":{"op":"literal","value":"string"}},"then":{"op":"matches","value":{"op":"path","path":"template"},"pattern":"^\\$(body|(path|query|caller)\\.[A-Za-z0-9_]+)$"},"else":{"op":"literal","value":false}},"then":{"op":"lookup","value":{"op":"path","path":"context"},"path":{"op":"path","path":"template"}},"else":{"op":"path","path":"template"}}}}}}';
