  @semantics_json = N'{"id":"respond-error","expression":{"op":"object","fields":{"contractId":{"op":"literal","value":"api-response.v1"},"disposition":{"op":"literal","value":"RESPONDED"},"status":{"op":"path","path":"status"},"headers":{"op":"literal","value":{"content-type":"application/json; charset=utf-8"}},"body":{"op":"object","fields":{"error":{"op":"object","fields":{"code":{"op":"path","path":"code"}}}}}}}}';
