  @semantics_json = N'{"id":"compose-response","expression":{"op":"let","bindings":{"failed":{"op":"if","when":{"op":"equals","left":{"op":"type","value":{"op":"path","path":"result.contractId"}},"right":{"op":"literal","value":"null"}},"then":{"op":"equals","left":{"op":"type","value":{"op":"path","path":"result.code"}},"right":{"op":"literal","value":"string"}},"else":{"op":"literal","value":false}}},"value":{"op":"object","fields":{"contractId":{"op":"literal","value":"api-response.v1"},"disposition":{"op":"literal","value":"RESPONDED"},"status":{"op":"if","when":{"op":"path","from":"failed","path":""},"then":{"op":"if","when":{"op":"matches","value":{"op":"path","path":"result.message"},"pattern":"_NOT_FOUND$"},"then":{"op":"literal","value":404},"else":{"op":"if","when":{"op":"matches","value":{"op":"path","path":"result.message"},"pattern":"_(SNAPSHOT_CHANGED|NAMESPACE_REQUIRED)$"},"then":{"op":"literal","value":409},"else":{"op":"literal","value":422}}},"else":{"op":"literal","value":200}},"headers":{"op":"literal","value":{"content-type":"application/json; charset=utf-8"}},"body":{"op":"if","when":{"op":"path","from":"failed","path":""},"then":{"op":"object","fields":{"error":{"op":"object","fields":{"code":{"op":"path","path":"result.code"},"message":{"op":"path","path":"result.message"}}}}},"else":{"op":"path","path":"result"}}}}}}';

EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability resolve-api-request\nintent: The frontdoor resolve stage in SEJ: match an HTTP request against the declared operations of sidefx-api-interface.v1, admit its caller and bind the input of the operation, or answer the refusal.\noutcome: the declared answer of the frontdoor\ninquiry: What does this request mean?\ninput contract resolve-api-request-request.v1 {\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"request\",\"interface\"],\"properties\":{\"request\":{\"type\":\"object\"},\"interface\":{\"type\":\"object\"},\"caller\":{\"type\":[\"object\",\"null\"]}}}\noutput contract resolve-api-request-result.v1 {\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"contractId\",\"disposition\"],\"properties\":{\"contractId\":{\"enum\":[\"api-response.v1\",\"api-resolution.v1\"]},\"disposition\":{\"enum\":[\"RESPONDED\",\"RESOLVED\"]}}}\ncli display outcome as json\nscenario resolve-api-request root terminal\ngiven: a frontdoor request\nwhen: the kernel evaluates the declared SEJ\nthen: the outcome is the declared answer\noperation resolve-api-request.evaluate kind invoke-port port resolve-api-request-evaluate\nplatform bind resolve-api-request-evaluate\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"resolve-request\"}","isMcpTooling":false}';
EXEC model.apply_capability_from_dsl @document = N'{"contractId":"capability-from-dsl-change.v1","source":"capability compose-api-response\nintent: The frontdoor respond stage in SEJ: compose api-response.v1 from the result of the capability of the operation.\noutcome: the declared answer of the frontdoor\ninquiry: What does this request mean?\ninput contract compose-api-response-request.v1 {\"type\":\"object\",\"additionalProperties\":false,\"required\":[\"result\"],\"properties\":{\"result\":{}}}\noutput contract compose-api-response-result.v1 {\"type\":\"object\",\"additionalProperties\":true,\"required\":[\"contractId\",\"disposition\"],\"properties\":{\"contractId\":{\"enum\":[\"api-response.v1\",\"api-resolution.v1\"]},\"disposition\":{\"enum\":[\"RESPONDED\",\"RESOLVED\"]}}}\ncli display outcome as json\nscenario compose-api-response root terminal\ngiven: a frontdoor request\nwhen: the kernel evaluates the declared SEJ\nthen: the outcome is the declared answer\noperation compose-api-response.evaluate kind invoke-port port compose-api-response-evaluate\nplatform bind compose-api-response-evaluate\nplatform: sda-authority-transformation-port.v1\nconfig: {\"transformationAuthorityRef\":\"semantic-transformation.authority.json\",\"transformationId\":\"compose-response\"}","isMcpTooling":false}';

COMMIT;
